const MODULE_CONTENT = {"en":{"cash-flow-statement":{"faq":[{"q":"Why is a bank's operating cash flow often negative?","a":"For a bank, giving loans is an operating activity, so rapid loan growth shows up as cash going out of operations, funded by deposits. Judge banks on asset quality, capital adequacy and deposit growth instead."},{"q":"Is negative free cash flow always bad?","a":"No. A company building capacity can have negative free cash flow for a year or two. It becomes a concern when it lasts for many years, when operating cash flow itself is weak, or when debt keeps rising without returns."},{"q":"Where is interest paid shown?","a":"Most non-financial companies show interest paid under financing activities, which Ind AS 7 allows. Some show it under operating activities. Check the company's policy note before comparing two companies."},{"q":"How many years should I look at?","a":"At least five. Single years are distorted by large orders, capex projects or working-capital swings. Totals over five years show the real pattern."}],"quiz":[{"q":"Which section of the cash flow statement shows cash from the core business?","o":["Dividend declaration","Operating activities","Investing activities","Financing activities"],"a":1,"e":"Operating cash flow reflects the cash generated by normal operations."},{"q":"Free cash flow is calculated as:","o":["Revenue minus debt","Equity plus reserves","Operating cash flow minus capital expenditure","Net profit plus dividends"],"a":2,"e":"FCF is the cash left after maintaining and growing the business."},{"q":"Operating cash flow is ₹400 crore and capex is ₹150 crore. What is free cash flow?","o":["₹150 crore","₹400 crore","₹550 crore","₹250 crore"],"a":3,"e":"400 − 150 = 250 crore."},{"q":"Why can a profitable company run out of cash?","o":["Sales are recorded before cash is received","Profit is always cash","Taxes are never paid","Dividends are always cash"],"a":0,"e":"Accrual accounting records sales and costs before the cash moves."},{"q":"Which is a warning sign in cash flow?","o":["Stable debt","Profit rising while operating cash flow stays negative","Operating cash flow rising with profit","Positive free cash flow"],"a":1,"e":"A persistent gap between profit and operating cash is a major red flag."},{"q":"Money spent on factories and machinery appears in:","o":["Financing activities","Shareholding pattern","Investing activities","Operating activities"],"a":2,"e":"Capex is an investing cash outflow."},{"q":"A company that pays dividends by borrowing is:","o":["Always stronger","Not allowed to pay dividends","Unaffected","Generally weaker than one paying from operating cash"],"a":3,"e":"Dividends funded by debt are not sustainable without growth in cash."},{"q":"Cash from issuing new shares appears under:","o":["Financing activities","Operating activities","Investing activities","Revenue"],"a":0,"e":"Equity raised from shareholders is a financing inflow."},{"q":"Repaying a loan is a:","o":["Revenue item","Financing outflow","Operating inflow","Investing inflow"],"a":1,"e":"Principal repayment is a financing cash outflow."},{"q":"What does positive free cash flow allow a company to do?","o":["Stop reporting profit","Issue shares automatically","Pay dividends, repay debt or expand without new borrowing","Avoid paying taxes"],"a":2,"e":"Free cash flow funds shareholder returns and growth."},{"q":"Maintenance capex is spending to:","o":["Enter new markets only","Pay dividends","Repay debt","Keep the existing business running"],"a":3,"e":"Maintenance capex keeps current operations going; growth capex expands them."},{"q":"If profit and operating cash flow move together over years, this suggests:","o":["Earnings are backed by cash","Earnings are manipulated","Taxes are rising","Debt is falling"],"a":0,"e":"Consistency between profit and cash supports earnings quality."},{"q":"Which increases the reliability of profit figures?","o":["Large exceptional gains","Operating cash flow close to net profit over several years","A single record quarter","Rising promoter pledge"],"a":1,"e":"Cash confirms that profit is real."},{"q":"A one-time sale of a property affects which section?","o":["Dividends","Shareholding","Investing activities","Operating activities only"],"a":2,"e":"Proceeds from selling assets are an investing inflow."},{"q":"Which cash flow line is most useful for judging the core business?","o":["Financing cash flow","Investing cash flow","Share capital","Operating cash flow"],"a":3,"e":"Operating cash flow shows how the main business generates cash."},{"q":"Why check the cash flow statement together with the balance sheet?","o":["Receivables and inventory on the balance sheet explain gaps in operating cash","They are unrelated","Cash flow includes all tax rules","Balance sheets have no cash"],"a":0,"e":"Working capital changes on the balance sheet explain differences in operating cash flow."},{"q":"Which pattern is a red flag in financing cash flow?","o":["Stable equity","Frequent new borrowing to fund day-to-day operations","Repaying debt from operating cash","Paying dividends from profits"],"a":1,"e":"Using debt for routine operations is unsustainable."},{"q":"A company receives a large one-time asset sale. Why be cautious?","o":["It reduces assets forever","It increases debt","It can hide weak operating cash flow","It is always illegal"],"a":2,"e":"One-time inflows can mask a weak core business."},{"q":"Which statement shows the actual movement of money during a period?","o":["Balance sheet","Shareholding pattern","Auditor's report","Cash flow statement"],"a":3,"e":"The cash flow statement records actual cash in and out."},{"q":"Free cash flow is most useful for:","o":["Judging how much cash shareholders could receive","Calculating the lot size","Deciding the stop-loss","Counting shareholders"],"a":0,"e":"FCF indicates the capacity for dividends, buybacks and debt repayment."},{"q":"A company with growing sales but falling operating cash flow may be:","o":["Paying off all debt","Extending credit to customers who pay late","Collecting cash faster","Reducing costs"],"a":1,"e":"Growth bought with credit can strain cash."}]}},"hi":{"cash-flow-statement":{"faq":[{"q":"बैंक का ऑपरेटिंग कैश फ़्लो अक्सर नेगेटिव क्यों होता है?","a":"बैंक के लिए क़र्ज़ देना परिचालन गतिविधि है, इसलिए तेज़ क़र्ज़ बढ़त ऑपरेशन से बाहर जाते नकद के रूप में दिखती है, जिसे जमा राशि फ़ंड करती है। बैंकों को संपत्ति की गुणवत्ता, पूँजी पर्याप्तता और जमा बढ़त पर परखें।"},{"q":"क्या नेगेटिव फ़्री कैश फ़्लो हमेशा बुरा है?","a":"नहीं। क्षमता बना रही कंपनी का फ़्री कैश फ़्लो एक-दो साल नेगेटिव रह सकता है। चिंता तब है जब यह कई साल चले, ऑपरेटिंग कैश फ़्लो ख़ुद कमज़ोर हो, या बिना रिटर्न के क़र्ज़ बढ़ता रहे।"},{"q":"चुकाया गया ब्याज कहाँ दिखता है?","a":"ज़्यादातर गैर-वित्तीय कंपनियाँ चुकाया गया ब्याज फ़ाइनेंसिंग गतिविधियों में दिखाती हैं, जिसकी Ind AS 7 अनुमति देता है। कुछ इसे ऑपरेटिंग में दिखाती हैं। दो कंपनियों की तुलना से पहले कंपनी की नीति वाला नोट देखें।"},{"q":"कितने साल देखने चाहिए?","a":"कम से कम पाँच। एक साल बड़े ऑर्डर, कैपेक्स प्रोजेक्ट या वर्किंग कैपिटल के उतार-चढ़ाव से बिगड़ जाता है। पाँच साल का जोड़ असली तस्वीर दिखाता है।"}],"quiz":[{"q":"कैश फ़्लो स्टेटमेंट का कौन सा हिस्सा मुख्य कारोबार से नकद दिखाता है?","o":["डिविडेंड घोषणा","संचालन गतिविधियाँ","निवेश गतिविधियाँ","वित्तपोषण गतिविधियाँ"],"a":1,"e":"संचालन कैश फ़्लो सामान्य कामकाज से पैदा नकद दर्शाता है।"},{"q":"फ़्री कैश फ़्लो निकाला जाता है:","o":["राजस्व − कर्ज़","इक्विटी + रिज़र्व","संचालन कैश फ़्लो − पूँजीगत व्यय","शुद्ध मुनाफ़ा + डिविडेंड"],"a":2,"e":"FCF वह नकद है जो कारोबार बनाए रखने और बढ़ाने के बाद बचता है।"},{"q":"संचालन कैश फ़्लो ₹400 करोड़ और कैपेक्स ₹150 करोड़ है। फ़्री कैश फ़्लो क्या है?","o":["₹150 करोड़","₹400 करोड़","₹550 करोड़","₹250 करोड़"],"a":3,"e":"400 − 150 = 250 करोड़।"},{"q":"मुनाफ़े वाली कंपनी के पास नकद कैसे ख़त्म हो सकता है?","o":["बिक्री नकद मिलने से पहले दर्ज होती है","मुनाफ़ा हमेशा नकद होता है","टैक्स कभी नहीं चुकाया जाता","डिविडेंड हमेशा नकद होते हैं"],"a":0,"e":"एक्रुअल लेखांकन बिक्री और खर्च को नकद चलने से पहले दर्ज करता है।"},{"q":"कैश फ़्लो में चेतावनी का संकेत कौन सा है?","o":["स्थिर कर्ज़","मुनाफ़ा बढ़े पर संचालन कैश फ़्लो नकारात्मक रहे","संचालन कैश फ़्लो मुनाफ़े के साथ बढ़े","सकारात्मक फ़्री कैश फ़्लो"],"a":1,"e":"मुनाफ़े और संचालन नकद के बीच लगातार अंतर बड़ी चेतावनी है।"},{"q":"फ़ैक्टरी और मशीनरी पर खर्च दिखता है:","o":["वित्तपोषण गतिविधियों में","शेयरहोल्डिंग पैटर्न में","निवेश गतिविधियों में","संचालन गतिविधियों में"],"a":2,"e":"कैपेक्स निवेश का नकद बहिर्वाह है।"},{"q":"कर्ज़ लेकर डिविडेंड देने वाली कंपनी:","o":["हमेशा मज़बूत","डिविडेंड नहीं दे सकती","अप्रभावित","संचालन नकद से देने वाली से आमतौर पर कमज़ोर"],"a":3,"e":"कर्ज़ से चुकाए डिविडेंड नकद वृद्धि के बिना टिकाऊ नहीं।"},{"q":"नए शेयर जारी करने से मिला नकद दिखता है:","o":["वित्तपोषण गतिविधियों में","संचालन गतिविधियों में","निवेश गतिविधियों में","राजस्व में"],"a":0,"e":"शेयरधारकों से जुटाई इक्विटी वित्तपोषण का नकद आगमन है।"},{"q":"कर्ज़ चुकाना है:","o":["राजस्व की मद","वित्तपोषण का नकद बहिर्वाह","संचालन का नकद आगमन","निवेश का नकद आगमन"],"a":1,"e":"मूलधन चुकाना वित्तपोषण का नकद बहिर्वाह है।"},{"q":"सकारात्मक फ़्री कैश फ़्लो कंपनी को क्या करने देता है?","o":["मुनाफ़ा रिपोर्ट करना बंद करना","स्वतः शेयर जारी करना","डिविडेंड, कर्ज़ चुकाना या बिना नया कर्ज़ विस्तार","टैक्स से बचना"],"a":2,"e":"फ़्री कैश फ़्लो शेयरधारक रिटर्न और विकास को फ़ंड करता है।"},{"q":"मेंटेनेंस कैपेक्स वह खर्च है जो:","o":["केवल नए बाज़ार में जाए","डिविडेंड दे","कर्ज़ चुकाए","मौजूदा कारोबार को चालू रखे"],"a":3,"e":"मेंटेनेंस कैपेक्स मौजूदा काम जारी रखता है; ग्रोथ कैपेक्स उसे बढ़ाता है।"},{"q":"अगर कई सालों में मुनाफ़ा और संचालन कैश फ़्लो साथ चलें, तो यह सुझाता है:","o":["कमाई को नकद का समर्थन है","कमाई में हेरफेर है","टैक्स बढ़ रहे हैं","कर्ज़ घट रहा है"],"a":0,"e":"मुनाफ़े और नकद में स्थिरता कमाई की गुणवत्ता का समर्थन करती है।"},{"q":"कौन सी बात मुनाफ़े के आँकड़ों की विश्वसनीयता बढ़ाती है?","o":["बड़े असाधारण लाभ","कई सालों तक संचालन कैश फ़्लो का शुद्ध मुनाफ़े के करीब होना","एक अकेली रिकॉर्ड तिमाही","बढ़ती प्रमोटर गिरवी"],"a":1,"e":"नकद पुष्टि करता है कि मुनाफ़ा असली है।"},{"q":"संपत्ति की एक-बार की बिक्री किस हिस्से को प्रभावित करती है?","o":["डिविडेंड को","शेयरहोल्डिंग को","निवेश गतिविधियों को","केवल संचालन गतिविधियों को"],"a":2,"e":"संपत्ति बेचने से मिली रकम निवेश का नकद आगमन है।"},{"q":"मुख्य कारोबार का आकलन करने के लिए कौन सी कैश फ़्लो पंक्ति सबसे उपयोगी है?","o":["वित्तपोषण कैश फ़्लो","निवेश कैश फ़्लो","शेयर पूँजी","संचालन कैश फ़्लो"],"a":3,"e":"संचालन कैश फ़्लो दिखाता है कि मुख्य कारोबार नकद कैसे पैदा करता है।"},{"q":"कैश फ़्लो स्टेटमेंट को बैलेंस शीट के साथ क्यों जाँचें?","o":["बैलेंस शीट की प्राप्य राशि और इन्वेंटरी संचालन नकद के अंतर समझाती है","वे अप्रासंगिक हैं","कैश फ़्लो में सारे टैक्स नियम होते हैं","बैलेंस शीट में नकद नहीं होता"],"a":0,"e":"बैलेंस शीट में वर्किंग कैपिटल के बदलाव संचालन नकद का अंतर समझाते हैं।"},{"q":"वित्तपोषण कैश फ़्लो में कौन सा पैटर्न चेतावनी है?","o":["स्थिर इक्विटी","रोज़मर्रा के कारोबार के लिए बार-बार नया कर्ज़","संचालन नकद से कर्ज़ चुकाना","मुनाफ़े से डिविडेंड देना"],"a":1,"e":"नियमित संचालन के लिए कर्ज़ का उपयोग टिकाऊ नहीं।"},{"q":"कंपनी को एक-बार का बड़ा संपत्ति बिक्री से नकद मिला। सावधानी क्यों?","o":["यह संपत्ति हमेशा के लिए घटाता है","यह कर्ज़ बढ़ाता है","यह कमज़ोर संचालन नकद को छिपा सकता है","यह हमेशा अवैध है"],"a":2,"e":"एक-बार की आमदनी कमज़ोर मुख्य कारोबार को छिपा सकती है।"},{"q":"कौन सा विवरण अवधि में पैसे की वास्तविक आवाजाही दिखाता है?","o":["बैलेंस शीट","शेयरहोल्डिंग पैटर्न","ऑडिटर की रिपोर्ट","कैश फ़्लो स्टेटमेंट"],"a":3,"e":"कैश फ़्लो स्टेटमेंट वास्तविक नकद आवक और जावक दर्ज करता है।"},{"q":"फ़्री कैश फ़्लो सबसे उपयोगी है यह समझने के लिए कि:","o":["शेयरधारकों को कितना नकद मिल सकता है","लॉट साइज़ क्या है","स्टॉप-लॉस कहाँ रखें","शेयरधारक कितने हैं"],"a":0,"e":"FCF डिविडेंड, बायबैक और कर्ज़ चुकाने की क्षमता दर्शाता है।"},{"q":"बढ़ती बिक्री के साथ घटता संचालन कैश फ़्लो बताता है कि कंपनी:","o":["सारा कर्ज़ चुका रही है","देर से भुगतान करने वाले ग्राहकों को उधार दे रही है","नकद तेज़ी से वसूल रही है","खर्च घटा रही है"],"a":1,"e":"उधार से हुई ग्रोथ नकद पर दबाव डालती है।"}]}}};
