const GLOSSARY_TERMS = [{"cat":"basics","term":{"en":"Dividend","hi":"डिविडेंड (लाभांश)"},"def":{"en":"A share of profit a company pays to its shareholders, usually per share.","hi":"कंपनी द्वारा शेयरधारकों को दिया जाने वाला मुनाफ़े का हिस्सा, आमतौर पर प्रति शेयर।"}},{"cat":"fundamental","term":{"en":"Cash flow statement","hi":"कैश फ़्लो स्टेटमेंट"},"def":{"en":"A record of the actual cash coming in and going out, from operations, investing and financing.","hi":"संचालन, निवेश और वित्तपोषण से वास्तव में आने और जाने वाले नकद का विवरण।"}},{"cat":"fundamental","term":{"en":"Cash flow from operations","hi":"संचालन कैश फ़्लो (Operating cash flow)"},"def":{"en":"Cash generated by the core business: cash received from customers minus cash paid for running costs and taxes.","hi":"मुख्य कारोबार से पैदा नकद: ग्राहकों से मिला नकद, घटा परिचालन खर्च और टैक्स का भुगतान।"}},{"cat":"fundamental","term":{"en":"Free cash flow","hi":"फ़्री कैश फ़्लो (FCF)"},"def":{"en":"Operating cash flow minus capital expenditure. The cash left after keeping the business running and growing.","hi":"संचालन कैश फ़्लो − पूँजीगत व्यय। कारोबार चलाने और बढ़ाने के बाद बचा नकद।"}},{"cat":"fundamental","term":{"en":"Capital expenditure (capex)","hi":"पूँजीगत व्यय (कैपेक्स)"},"def":{"en":"Money spent on long-lived assets such as factories, machinery or technology.","hi":"फ़ैक्टरी, मशीनरी या तकनीक जैसी लंबे समय तक रहने वाली संपत्तियों पर खर्च।"}}];
